#include <iostream>
#include <numeric>
#include <vector>

int main() {
    std::vector<int> values;
    values.reserve(1000); // reserve capacity, not element count
    for (int i = 0; i < 1000; ++i) values.push_back(i);
    std::cout << "size=" << values.size() << ", sum=" << std::accumulate(values.begin(), values.end(), 0LL) << '\n';
}
